import{_ as t,c as a,o as n,ag as s}from"./chunks/framework.CoPVQkzc.js";const p=JSON.parse('{"title":"Quick Start Tutorial","description":"Get your first channel running in minutes","frontmatter":{"title":"Quick Start Tutorial","description":"Get your first channel running in minutes"},"headers":[],"relativePath":"engine/quick_start_tutorial.md","filePath":"engine/quick_start_tutorial.md","lastUpdated":1788476353000}'),o={name:"engine/quick_start_tutorial.md"};function r(i,e,l,c,d,h){return n(),a("div",null,e[0]||(e[0]=[s(`<h1 id="quick-start-tutorial" tabindex="-1">Quick Start Tutorial <a class="header-anchor" href="#quick-start-tutorial" aria-label="Permalink to &quot;Quick Start Tutorial&quot;">​</a></h1><p>This tutorial walks you through creating your first channel to receive, transform, and route an HL7 message.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>OIE Server is installed and running (see <a href="./installation.html">Installation</a>)</li><li>A compatible Administrator launcher is installed (see <a href="./desktop_administrator.html">Desktop Administrator</a> for the options)</li></ul><h2 id="step-1-log-in" tabindex="-1">Step 1: Log in <a class="header-anchor" href="#step-1-log-in" aria-label="Permalink to &quot;Step 1: Log in&quot;">​</a></h2><ol><li>Launch the Administrator client</li><li>The <strong>Server</strong> field is pre-filled with the server address (default: <code>https://localhost:8443</code>). Change it if your server uses a different address or port.</li><li>Log in with your credentials (default: <code>admin</code> / <code>admin</code>)</li><li>On first login, you will be prompted to set up your user account, including choosing a new password and entering your personal information</li></ol><h2 id="step-2-create-a-new-channel" tabindex="-1">Step 2: Create a new channel <a class="header-anchor" href="#step-2-create-a-new-channel" aria-label="Permalink to &quot;Step 2: Create a new channel&quot;">​</a></h2><ol><li>In the left-hand navigation panel, click <strong>Channels</strong> to open the Channels view</li><li>In the <strong>Channel Tasks</strong> panel on the left, click <strong>New Channel</strong></li><li>Fill in the <strong>Summary</strong> tab: <ul><li><strong>Name:</strong> <code>My First Channel</code></li><li><strong>Description:</strong> <code>Receives HL7 messages and writes to file</code></li><li><strong>Data Types:</strong> Leave as default (HL7 v2.x)</li></ul></li><li>Navigate to the <strong>Source</strong> tab</li></ol><h2 id="step-3-configure-the-source-connector" tabindex="-1">Step 3: Configure the source connector <a class="header-anchor" href="#step-3-configure-the-source-connector" aria-label="Permalink to &quot;Step 3: Configure the source connector&quot;">​</a></h2><p>The source connector defines how messages enter the channel.</p><ol><li>Select the <strong>Source</strong> tab</li><li>Set <strong>Connector Type</strong> to <strong>TCP Listener</strong></li><li>Configure: <ul><li><strong>Local Address:</strong> Select <strong>All interfaces</strong> (listens on <code>0.0.0.0</code>)</li><li><strong>Local Port:</strong> <code>6661</code></li><li><strong>Transmission Mode:</strong> MLLP (default for HL7)</li></ul></li><li>The source will now listen for incoming HL7 messages on port 6661</li></ol><h2 id="step-4-configure-a-destination-connector" tabindex="-1">Step 4: Configure a destination connector <a class="header-anchor" href="#step-4-configure-a-destination-connector" aria-label="Permalink to &quot;Step 4: Configure a destination connector&quot;">​</a></h2><p>Destinations define where processed messages are sent.</p><ol><li>Select the <strong>Destinations</strong> tab</li><li>The default destination <code>Destination 1</code> is already created</li><li>Set <strong>Connector Type</strong> to <strong>File Writer</strong></li><li>Configure: <ul><li><strong>Directory:</strong> <code>/tmp/oie-output</code> (or a Windows path like <code>C:\\oie-output</code>)</li><li><strong>File Name:</strong> <code>\${message.messageId}.hl7</code></li><li><strong>Template:</strong> <code>\${message.encodedData}</code> (writes the transformed message)</li></ul></li></ol><h2 id="step-5-add-a-simple-transformer-optional" tabindex="-1">Step 5: Add a simple transformer (optional) <a class="header-anchor" href="#step-5-add-a-simple-transformer-optional" aria-label="Permalink to &quot;Step 5: Add a simple transformer (optional)&quot;">​</a></h2><ol><li>On the <strong>Destinations</strong> tab, click <strong>Edit Transformer</strong></li><li>Add a new <strong>Mapper</strong> step: <ul><li><strong>Variable:</strong> <code>patientName</code></li><li><strong>Mapping:</strong> <code>msg[&#39;PID&#39;][&#39;PID.5&#39;][&#39;PID.5.1&#39;].toString()</code> (extracts patient last name)</li></ul></li><li>Add a <strong>Message Builder</strong> step to modify a field if desired</li></ol><h2 id="step-6-deploy-and-test" tabindex="-1">Step 6: Deploy and test <a class="header-anchor" href="#step-6-deploy-and-test" aria-label="Permalink to &quot;Step 6: Deploy and test&quot;">​</a></h2><ol><li>Click <strong>Save</strong> (Ctrl+S) to save the channel. You will be returned to the Channels view.</li><li>Select your channel in the channel list</li><li>In the <strong>Channel Tasks</strong> panel, click <strong>Deploy Channel</strong></li><li>You will be taken to the Dashboard, where the channel status should show as <strong>Started</strong> (green)</li></ol><h3 id="send-a-test-message" tabindex="-1">Send a test message <a class="header-anchor" href="#send-a-test-message" aria-label="Permalink to &quot;Send a test message&quot;">​</a></h3><p>You can send a test HL7 message using a TCP client such as <a href="https://hapifhir.github.io/hapi-hl7v2/hapi-testpanel/" target="_blank" rel="noreferrer">HAPI Test Panel</a> or <a href="https://hl7spy.ca/" target="_blank" rel="noreferrer">HL7Spy</a>, or use the built-in <strong>Send Message</strong> dialog:</p><ol><li>On the <strong>Dashboard</strong>, select your channel in the table</li><li>In the <strong>Dashboard Tasks</strong> panel on the left, click <strong>Send Message</strong></li><li>Paste a sample HL7 message into the text area (or click <strong>Open Text File</strong> to load one from disk):</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>MSH|^~\\&amp;|SENDING|FACILITY|RECEIVING|FACILITY|20240101120000||ADT^A01|MSG00001|P|2.3</span></span>
<span class="line"><span>EVN|A01|20240101120000</span></span>
<span class="line"><span>PID|1||12345^^^MRN||DOE^JOHN||19800101|M</span></span>
<span class="line"><span>PV1|1|I|ICU^101^A</span></span></code></pre></div><ol start="4"><li>Verify the destinations listed below the message are checked</li><li>Click <strong>Process Message</strong></li><li>Check your output directory for the written file</li></ol><h2 id="step-7-monitor-results" tabindex="-1">Step 7: Monitor results <a class="header-anchor" href="#step-7-monitor-results" aria-label="Permalink to &quot;Step 7: Monitor results&quot;">​</a></h2><ol><li>On the <strong>Dashboard</strong>, view message statistics (Received, Filtered, Queued, Sent, Errored) for your channel</li><li>To inspect individual messages, select the channel and click <strong>View Messages</strong> in the Dashboard Tasks panel (or double-click the channel row) to open the <strong>Message Browser</strong></li><li>In the Message Browser, view the raw content, transformed content, encoded data, and any errors for each message</li></ol><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Learn about <a href="./channels_and_connectors.html">Channels and Connectors</a> in depth</li><li>Explore all available <a href="./connector_reference.html">Connectors</a></li><li>Set up <a href="./filters_and_transformers.html">Filters and Transformers</a> for advanced routing</li><li>Read the <a href="./javascript_scripting_reference.html">JavaScript Scripting Reference</a> for custom logic</li></ul>`,27)]))}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
